 b=p.chromium.launch(executable_path='/usr/bin/chromium',headless=True,args=['--no-sandbox']); page=b.new_page(viewport={'width':1280,'height':1000},accept_downloads=True);errors=[];remote=[];page.on('pageerror',lambda e:errors.append(str(e)));page.on('request',lambda r:remote.append(r.url) if r.url.startswith(('http:','https:')) else None);page.set_content(Path(__file__).with_name('index.html').read_text());assert page.locator('#output').is_visible();print(page.locator('#metrics').inner_text());assert page.locator('#rows tr').count()==16;page.screenshot(path='desktop.png',full_page=True);page.locator('#speeds').fill('20, 25, 30');assert not page.locator('#output').is_visible();page.locator('#run').click();assert page.locator('#rows tr').count()==3
 with page.expect_download() as dl:page.locator('#export').click()
 assert 'point,speed_kmh' in Path(dl.value.path()).read_text();page.locator('#fa').fill('34,34');page.locator('#run').click();assert not page.locator('#output').is_visible();assert '重複' in page.locator('#message').inner_text();page.locator('#reset').click();assert page.locator('#rows tr').count()==16;page.set_viewport_size({'width':390,'height':844});assert page.evaluate('document.documentElement.scrollWidth <= innerWidth');page.screenshot(path='mobile.png',full_page=True);assert not errors and not remote;print('Chromium: initial, edit, recompute, CSV, duplicate validation, reset, mobile, no errors or network passed');b.close()
